{"function": "() => {
    try {
        // Check if GameBootstrap class is registered
        const js = window.cc?.js;
        const classMap = js?._nameToClass || {};

        const gameClasses = Object.keys(classMap).filter(k => 
            k.includes('Game') || k.includes('Bootstrap') || k.includes('Grid') || k.includes('Score') || k.includes('Input') || k.includes('Tetromino')
        );

        // Also check by UUID
        const uuidMap = js?._uuidToClass || {};
        const gameUUIDs = Object.keys(uuidMap).filter(k => {
            const cls = uuidMap[k];
            const name = cls?.name || '';
            return name.includes('Game') || name.includes('Bootstrap') || name.includes('Grid');
        });

        return {
            registeredGameClasses: gameClasses,
            gameClassUUIDs: gameUUIDs.map(uuid => ({ uuid, name: uuidMap[uuid]?.name }))
        };
    } catch(e) {
        return { error: e.message };
    }
}"}

