toolRequests.arguments:
{"function": "() => {
    // Check all registered CC classes
    const js = window.cc?.js;
    const classMap = js?._nameToClass || {};
    const allClasses = Object.keys(classMap);

    // Check cc version
    const version = window.cc?.VERSION;

    // Check if there are any user scripts (non-engine classes)
    const enginePrefixes = ['cc', 'CC', 'sp', 'dragonBones', 'Spine', 'PhysicsSystem', 'RigidBody'];
    const userClasses = allClasses.filter(name => 
        !enginePrefixes.some(p => name.startsWith(p)) && name.length > 2
    ).slice(0, 30);

    return {
        ccVersion: version,
        totalClasses: allClasses.length,
        userClasses: userClasses
    };
}"}

