{"function": "() => {
    const js = window.cc?.js;

    // Try to get GameBootstrap class directly
    const GameBootstrap = js?.getClassByName?.('GameBootstrap');
    const GameMain = js?.getClassByName?.('GameMain');
    const Grid = js?.getClassByName?.('Grid');

    // Also check if scripts were loaded via module system
    const assetManager = window.cc?.assetManager;
    const bundles = assetManager?._bundles;
    const bundleKeys = bundles ? [...bundles.keys()] : [];

    // Check if systemjs loaded any game scripts
    const systemjsRegistry = window.System?._nodeModulesRegistry || window.System?.resolve ? 'present' : 'absent';

    return {
        GameBootstrap: GameBootstrap?.name || null,
        GameMain: GameMain?.name || null,
        Grid: Grid?.name || null,
        bundles: bundleKeys,
        systemjs: systemjsRegistry
    };
}"}

