{"function": "() => {
    try {
        const scene = window.cc?.director?.getScene();
        const canvas = scene?._children?.[0]; // Canvas node

        if (!canvas) return { error: 'No canvas node' };

        // Get all components on the Canvas node
        const comps = canvas._components || [];
        const compInfo = comps.map(c => ({
            name: c.constructor?.name,
            enabled: c._enabled,
            uuid: c._id
        }));

        // Check canvas node internal state
        return {
            canvasName: canvas.name,
            componentCount: comps.length,
            components: compInfo,
            // Check if there are any "missing" script markers
            missingScripts: canvas._objFlags,
            childCount: canvas._children?.length || 0
        };
    } catch(e) {
        return { error: e.message };
    }
}"}

