    try {
        const js = window.cc?.js;
        const GameBootstrap = js?.getClassByName?.('GameBootstrap');

        // Get the UUID associated with the class at runtime
        const runtimeUUID = GameBootstrap?.__cid__ || GameBootstrap?.prototype?.__cid__;

        // Also check via classId API
        const classId = window.cc?.js?.getClassId?.(GameBootstrap);

        // What's in the scene file (compressed UUID from scene.scene)
        const sceneTypeId = '6a532zrQ/FOb46a2IuR8D8k';

        // Try to get class by the scene file type id
        const classBySceneId = window.cc?.js?.getClassById?.(sceneTypeId);

        return {
            runtimeUUID: runtimeUUID,
            classId: classId,
            sceneTypeId: sceneTypeId,
            classBySceneId: classBySceneId?.name || null,
            match: classId === sceneTypeId
        };
    } catch(e) {
        return { error: e.message };
    }
}"}

