toolRequests.arguments:
{"function": "() => {
    try {
        const scene = window.cc?.director?.getScene();
        const canvas = scene?._children?.[0];
        const js = window.cc?.js;
        const GameBootstrap = js?.getClassByName?.('GameBootstrap');

        if (!GameBootstrap) return { error: 'GameBootstrap class not found' };
        if (!canvas) return { error: 'Canvas node not found' };

        // Add the component manually
        const comp = canvas.addComponent(GameBootstrap);
        return {
            success: !!comp,
            compName: comp?.constructor?.name,
            nodeChildCount: canvas._children?.length || 0,
            error: null
        };
    } catch(e) {
        return { error: e.message, stack: e.stack?.split('\n').slice(0,5).join('\n') };
    }
}"}

