{"function": "() => {
    try {
        // Check how scripts are loaded - inspect asset module association
        const assetManager = window.cc?.assetManager;

        // Look for the GameBootstrap script asset
        const bootstrapUUID = '6a532ceb-43f1-4e6f-8e9a-d88b91f03f24';
        const mainUUID = '05642d7e-9043-4d55-b6ca-e950f7569cc4';

        // Check if these UUIDs are in the asset database
        const items = assetManager?._files;
        const itemType = typeof items;

        // Try direct asset lookup
        const bootstrapAsset = assetManager?.assets?.get?.(bootstrapUUID);

        // Try to get the dependUtil to see module dependencies
        const depend = assetManager?.dependUtil;
        const bootstrapDeps = depend?.getDeps?.(bootstrapUUID);

        // Check bundles
        const mainBundle = assetManager?.getBundle?.('main');
        const mainBundleConfig = mainBundle?._config;

        return {
            itemType,
            bootstrapAsset: bootstrapAsset ? 'found' : 'not found',
            bootstrapDeps,
            mainBundle: !!mainBundle,
            mainBundleVersion: mainBundleConfig?.version,
            mainBundleName: mainBundleConfig?.name
        };
    } catch(e) {
        return { error: e.message };
    }
}"}

