    try {
        const assetManager = window.cc?.assetManager;
        const mainBundle = assetManager?.getBundle?.('main');

        // Check what assets the main bundle knows about
        const config = mainBundle?._config;

        // Try to get the raw bundle data
        const paths = config?._pathList || [];
        const uuids = config?._uuidList || [];

        // More direct - get the raw config data
        const rawData = config?._raw || {};
        const hasScripts = JSON.stringify(rawData).includes('6a532');

        // Get all known UUIDs in main bundle
        const allPaths = config?.paths?._map ? Object.keys(config.paths._map) : [];

        // Check if scene is properly loaded
        const sceneUUID = '15c386b2-8c4a-4be1-aefb-9fe6f0bbd294';
        const sceneAsset = assetManager?.assets?.get?.(sceneUUID);

        return {
            hasScripts,
            pathCount: allPaths.length,
            samplePaths: allPaths.slice(0, 10),
            sceneAsset: sceneAsset ? 'found' : 'not found',
            sceneClass: sceneAsset?.constructor?.name
        };
    } catch(e) {
        return { error: e.message };
    }
}"}

